class ActionHistory:
    def __init__(self):
        self.undo_stack = []
        self.redo_stack = []
    def perform(self, act):
        self.undo_stack.append(act)
        self.redo_stack.clear()
    def undo(self):
        if self.undo_stack:
            act = self.undo_stack.pop()
            self.redo_stack.append(act)
            return act
